import os
import subprocess
import sys
from pathlib import Path

BUILD_DRIVE = Path(__file__).resolve().parent / "build-drive.sh"

EXPORTED = """\
# This file was autogenerated by uv via the following command:
#    uv export --frozen --no-dev --no-hashes --no-emit-project
pyside6-essentials==6.4.2
    # via mediatagger
python-mpv==0.9.1
    # via mediatagger
shiboken6==6.4.2
    # via pyside6-essentials
"""


def fake_command(bin_dir, name, script):
    (bin_dir / name).write_text(f"#!/bin/sh\n{script}\n")
    (bin_dir / name).chmod(0o755)


def fake_build_env(tmp_path, record):
    """Fake uv, apt-ftparchive and python3.13 on PATH, a Pi-like apt root with one .deb, home under tmp_path."""
    bin_dir = tmp_path / "bin"
    bin_dir.mkdir()
    (tmp_path / "exported.txt").write_text(EXPORTED)
    record.mkdir()
    fake_command(bin_dir, "uv", f"""
if [ "$1" = export ]; then
  shift
  for a; do
    case "$a" in --frozen|--no-dev|--no-hashes|--no-emit-project) ;; *) exit 2;; esac
  done
  [ $# -eq 4 ] || exit 2
  cat "{tmp_path / 'exported.txt'}"
  exit 0
fi
i=1; while [ -e "{record}/$i" ]; do i=$((i+1)); done
mkdir "{record}/$i"
printf '%s\\0' "$@" > "{record}/$i/args"
prev=
for a; do
  case "$prev" in -r|--requirement|--requirements) cp "$a" "{record}/$i/requirements";; esac
  case "$a" in --requirement=*|--requirements=*) cp "${{a#*=}}" "{record}/$i/requirements";; esac
  prev=$a
done""")
    fake_command(bin_dir, "apt-ftparchive", "printf 'Package: libmpv2\\n'")
    fake_command(bin_dir, "python3.13", f'exec "{sys.executable}" "$@"')
    aptpi = tmp_path / "aptpi"
    archives = aptpi / "var" / "cache" / "apt" / "archives"
    archives.mkdir(parents=True)
    (archives / "libmpv2_0.39.0-3_arm64.deb").write_bytes(b"!<arch>\ndeb")
    (tmp_path / "home").mkdir()
    return {
        **os.environ,
        "PATH": f"{bin_dir}{os.pathsep}{os.environ['PATH']}",
        "HOME": str(tmp_path / "home"),
        "APTPI": str(aptpi),
    }


def uv_pip_install_calls(record):
    calls = []
    for call in sorted(record.iterdir(), key=lambda d: int(d.name)):
        args = [a.decode() for a in (call / "args").read_bytes().split(b"\0")[:-1]]
        if args[:2] != ["pip", "install"]:
            continue
        requirements = call / "requirements"
        calls.append({
            "args": args[2:],
            "requirements": requirements.read_text() if requirements.exists() else "",
        })
    return calls


def requirement_specs(text):
    return {
        line.split(";")[0].strip()
        for line in text.splitlines()
        if line.strip() and not line.strip().startswith("#")
    }


def option_value(args, name):
    return next((args[i + 1] for i, a in enumerate(args[:-1]) if a == name), None)


def positional_specs(args):
    takes_value = {"--python", "--target", "-r", "--requirement", "--requirements"}
    specs, skip = set(), False
    for a in args:
        if skip:
            skip = False
        elif a in takes_value:
            skip = True
        elif not a.startswith("-"):
            specs.add(a)
    return specs


def test_build_drive_installs_exactly_the_uv_exported_locked_packages_into_the_drive_lib_for_the_pis_python(tmp_path):
    record = tmp_path / "uv-calls"
    env = fake_build_env(tmp_path, record)
    drive = tmp_path / "drive"
    drive.mkdir()

    subprocess.run(["sh", str(BUILD_DRIVE), str(drive)], env=env)

    lib = drive / "mediatagger" / "lib-linux-aarch64-cp313"
    installs = [
        {
            "python": option_value(call["args"], "--python"),
            "target": option_value(call["args"], "--target"),
            "specs": positional_specs(call["args"]) | requirement_specs(call["requirements"]),
        }
        for call in uv_pip_install_calls(record)
    ]
    assert installs == [{
        "python": "/usr/bin/python3.13",
        "target": str(lib),
        "specs": requirement_specs(EXPORTED),
    }]
